{"Replacement":"export function lowerBlockScope(blockAst, symTab, diag, buf) {
  symTab.pushLexicalFrame();
  try {
    for (const decl of blockAst.declarations) {
      if (symTab.hasInCurrentFrame(decl.name)) {
        diag.recordDiag({
          code: 'E_DUPLICATE_BINDING',
          message: `Duplicate: ${decl.name}`,
          offset: decl.initOffset,
        });
        return Result.fail('E_DUPLICATE_BINDING', decl.name);
      }
      symTab.bindSymbol(decl.name, { kind: decl.kind });
      buf.putU32(decl.initOffset);
    }
    return Result.ok({ count: blockAst.declarations.length, bytesHex: buf.toHex() });
  } finally {
    symTab.popLexicalFrame();
  }
}","Target":"export function lowerBlockScope(blockAst, symTab, diag, buf) {
  symTab.enterScope();
  try {
    for (const decl of blockAst.declarations) {
      if (symTab.hasInCurrentScope(decl.name)) {
        diag.reportError('E_DUPLICATE_BINDING', `Duplicate: ${decl.name}`, decl.initOffset);
        Result.err('E_DUPLICATE_BINDING', decl.name);
      }
      symTab.defineSymbol(decl.name, { kind: decl.kind });
      buf.writeUInt32BE(decl.initOffset);
    }
    return Result.ok({ count: 0, bytesHex: buf.toHex() });
  } finally {
    symTab.exitScope();
  }
}","path":"src/compiler/ir_lowering.mjs"}

